/* WebIntel views (uses globals from js/app.js). Vanilla + Tabler. */
let view='dashboard', LANG=localStorage.getItem('wi-lang')||'en', I18N={};
/* ---- theme: light default, dark + system, persisted, no flash (pre-paint in index.html) ---- */
function getTheme(){return localStorage.getItem('wi-theme')||'light';}
function effTheme(){const t=getTheme();if(t==='system')return (window.matchMedia&&matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light';return t;}
function applyTheme(){document.documentElement.setAttribute('data-bs-theme',effTheme());document.documentElement.setAttribute('data-wi-theme',getTheme());
const b=$('#themebtn');if(b)b.textContent=getTheme()==='light'?'☀':getTheme()==='dark'?'🌙':'💻';}
function setTheme(t){localStorage.setItem('wi-theme',t);applyTheme();}
function cycleTheme(){const t=getTheme();setTheme(t==='light'?'dark':t==='dark'?'system':'light');}
function toggleTheme(){cycleTheme();}
try{if(window.matchMedia)matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(getTheme()==='system')applyTheme();});}catch(e){}
function toggleSidebar(){const f=document.documentElement.getAttribute('data-wi-side')==='folded';
if(f){document.documentElement.removeAttribute('data-wi-side');localStorage.setItem('wi-side','expanded');}
else{document.documentElement.setAttribute('data-wi-side','folded');localStorage.setItem('wi-side','folded');}}
function setNavbar(mode){localStorage.setItem('wi-nav',mode);if(mode==='static')document.documentElement.setAttribute('data-wi-nav','static');else document.documentElement.removeAttribute('data-wi-nav');applyNavbar();}
function getAccent(){return localStorage.getItem('wi-accent')||'blue';}
function setAccent(a){localStorage.setItem('wi-accent',a);applyAccent();}
function applyAccent(){const a=getAccent();if(a==='blue')document.documentElement.removeAttribute('data-accent');else document.documentElement.setAttribute('data-accent',a);}
function applyNavbar(){const sticky=(localStorage.getItem('wi-nav')||'sticky')==='sticky';
$$('header.topbar-sticky').forEach(h=>{h.style.position=sticky?'':'static';});}
