async function projectAdd(){openModal(`<h3>New project</h3><form onsubmit="projectSave(event)">${field('Name','name')}${field('Description','description','',{type:'textarea',rows:2})}<div class="btn-list"><button class="btn btn-primary">Create</button><button type="button" class="btn" onclick="closeModal()">Cancel</button></div></form>`);}
async function projectSave(e){e.preventDefault();const v=formVals(e.target);if(!v.name.trim()){toast('Name required');return}try{const r=await post('/api/v1/projects',{name:v.name.trim(),description:v.description||''});closeModal();toast('Project #'+r.id);load();}catch(err){toast('Create failed: '+String(err).slice(0,200))}}
