async function targetBulkDel(){const ids=[...window.pgTargets.sel];if(!ids.length){toast('Select rows first (checkboxes)');return}
if(!await confirmDlg(`Delete ${ids.length} selected target(s)? Targets with jobs are skipped.`))return;
try{const r=await post('/api/v1/targets/bulk-delete',{ids});window.pgTargets.sel.clear();toast(`Deleted ${r.deleted.length}, skipped ${Object.keys(r.skipped||{}).length}`);load();}catch(e){toast('Bulk delete failed: '+String(e).slice(0,200))}}
