async function testTarget(id,btn){try{await runAction({btn,title:'Test target '+id,stages:['Validating','Connecting','Scoring target'],
fn:async(op)=>{const r=await post(`/api/v1/targets/${id}/test`,{});opStage(op.id,'Done');return r;},
onDone:(r)=>{toast((r.ok?'✓ ok':'✕ failed')+` · http=${r.http_status??'—'} · strategy=${r.strategy||'—'}${r.error?' · '+r.error:''}`.slice(0,280));load();}});}catch(e){toast('Test failed: '+String(e).slice(0,300));load();}}
async function targetScan(id,btn){try{await runAction({btn,title:'Recon target '+id,stages:['Creating job','Running pipeline','Recon enrichment','Saving results'],
fn:async(op)=>{const t=await api('/api/v1/targets/'+id);opStage(op.id,'Running pipeline');const j=await post('/api/v1/jobs',{project_id:t.project_id,target_id:id,url:t.url,strategy:'AUTO'});const r=await post(`/api/v1/jobs/${j.job_id}/run`,{});return{...r,job_id:j.job_id};},
onDone:(r)=>{toast(`Scan ${r.status}, prices=${(r.prices||[]).length}`);go('job',r.job_id);}});}catch(e){toast('Scan failed: '+String(e).slice(0,300));load();}}
