function feedActions(i,ix){const r=i.ref||{};const b=[];
if(r.target)b.push(`<button class="btn btn-sm" onclick="go('target',${+r.target||0})">Open target</button>`);
if(r.finding)b.push(`<button class="btn btn-sm" onclick="openFinding(${+r.finding||0})">Open finding</button>`);
if(r.alert)b.push(`<button class="btn btn-sm" onclick="alertOpen(${+r.alert||0})">Open alert</button>`);
if(r.event)b.push(`<button class="btn btn-sm" onclick="go('events')">Open events</button>`);
b.push(`<button class="btn btn-sm" onclick="feedInvestigate(${ix})">Investigate</button>`);
return b.join(' ');}
async function feedInvestigate(ix){const ref=((window._feedItems||[])[ix]||{}).ref||{};const q=ref.target?`target ${ref.target}`:ref.finding?`finding ${ref.finding}`:'intel';
try{const r=await post('/api/v1/investigations',{title:'Investigation from feed: '+q});toast('Investigation #'+r.id);go('investigation',r.id);}catch(e){toast(String(e).slice(0,200))}}
