async function addReport(e){e.preventDefault();const f=e.target;const btn=f.querySelector('button');try{await runAction({btn,title:'Generate report',stages:['Collecting data','Building findings','Rendering report'],
fn:async(op)=>{const r=await post('/api/v1/reports',{kind:f.kind.value||'price',product_id:+f.product_id.value||0,project:f.project.value});return r;},
onDone:(r)=>{toast('Report #'+r.id);viewReport(r.id);load();}});}catch(err){toast(String(err).slice(0,300));}}
