async function chat(e){e.preventDefault();const box=document.querySelector('#ans');box.innerHTML='<span class="status warn">AI-generated — verify against cited evidence</span><div class="text-muted small">Asking…</div>';
try{const r=await post('/api/v1/ai/chat',{messages:[{role:'user',content:e.target.q.value}]});const txt=(r.answer||r.content||JSON.stringify(r)).toString().slice(0,3000);
box.innerHTML=`<span class="status warn">AI-generated — interpretation, not observed fact</span><div class="mt-1">${esc(txt)}</div>${r.citations?`<div class="text-muted small mt-1">Observed evidence: ${esc(JSON.stringify(r.citations).slice(0,300))}</div>`:''}`;}catch(e2){box.textContent=String(e2).slice(0,300);}}
async function doSearch(e){e.preventDefault();const f=e.target;const mode=f.mode?f.mode.value:'keyword';const q=(f.q.value||'').trim();const url=mode==='semantic'?'/api/v1/search/semantic?q='+encodeURIComponent(q):'/api/v1/search?q='+encodeURIComponent(q);const box=document.querySelector('#res');box.innerHTML='<div class="text-muted">Searching…</div>';
try{const r=await api(url);const items=r.items||[];
if(!items.length){box.innerHTML=emptyBox('No results found.','Try a different spelling, or start a new investigation to collect fresh intelligence.','+ New Investigation','new-investigation');return;}
const groups={};items.forEach(it=>{const k=it.kind||it.type||'result';(groups[k]=groups[k]||[]).push(it);});
box.innerHTML=Object.entries(groups).map(([k,rows])=>`<h4 class="mt-2">${esc(k)} (${rows.length})</h4>`+rows.slice(0,10).map(it=>{const title=it.title||it.name||it.domain||it.url||it.value||('result #'+(it.id??''));const dom=it.domain||it.url||q;
return `<div class="d-flex gap-2 align-items-center mb-1"><span class="text-truncate" style="max-width:420px">${esc(String(title).slice(0,90))}</span><span class="ms-auto"><button class="btn btn-sm" onclick="gSearchInv('${esc(String(dom)).replace(/'/g,"\\'")}')">Investigate</button></span></div>`;}).join('')).join('');}catch(err){box.innerHTML=errBox(err);}}
