async function addOrg(e){e.preventDefault();await post('/api/v1/orgs',{name:e.target.name.value});load()}
async function orgBrand(id){let b={};try{b=(await api(`/api/v1/orgs/${id}/branding`)).branding||{}}catch(e){}
openModal(`<h3>Branding (org #${id})</h3><form onsubmit="orgBrandSave(event,${id})">${field('Branding JSON','branding',JSON.stringify(b,null,1),{type:'textarea',rows:5})}<div class="btn-list"><button class="btn btn-primary">Save</button><button type="button" class="btn" onclick="closeModal()">Cancel</button></div></form>`);}
async function orgBrandSave(e,id){e.preventDefault();let b;try{b=JSON.parse(e.target.branding.value)}catch(err){toast('Invalid JSON');return}
try{await put(`/api/v1/orgs/${id}/branding`,{branding:b});closeModal();toast('Branding saved');load();}catch(err){toast(String(err).slice(0,300))}}
async function memberAdd(e){e.preventDefault();const v=formVals(e.target);try{await post('/api/v1/memberships',{email:v.email,role:v.role});toast('Member added');load();}catch(err){toast('Add failed: '+String(err).slice(0,300))}}
async function memberRole(id,cur){const r=prompt('New role (builtin or custom):',cur);if(!r)return;try{await put('/api/v1/memberships/'+id,{role:r.trim()});toast('Role updated');load();}catch(e){toast(String(e).slice(0,300))}}
const ROLE_ACTIONS=['read','collect','research','alert','ai','configure','users'];
async function roleAdd(){openModal(`<h3>New custom role</h3><form onsubmit="roleSave(event)">${field('Name (letters, digits, - _)','name')}${ROLE_ACTIONS.map(a=>`<label class="form-check"><input type="checkbox" name="p_${a}" class="form-check-input"> ${a}</label>`).join('')}<div class="btn-list mt-2"><button class="btn btn-primary">Create</button><button type="button" class="btn" onclick="closeModal()">Cancel</button></div></form>`);}
async function roleSave(e){e.preventDefault();const v=formVals(e.target);const perms=ROLE_ACTIONS.filter(a=>v['p_'+a]);
try{await post('/api/v1/roles',{name:v.name,permissions:perms});closeModal();toast('Role created');load();}catch(err){toast('Create failed: '+String(err).slice(0,300))}}
async function roleEdit(name){let cur=[];try{const r=await api('/api/v1/roles');const hit=(r.custom||[]).find(x=>x.name===name);cur=hit?hit.permissions:[]}catch(e){}
openModal(`<h3>Edit role ${esc(name)}</h3><form onsubmit="roleUpdate(event,'${esc(name)}')">${ROLE_ACTIONS.map(a=>`<label class="form-check"><input type="checkbox" name="p_${a}" class="form-check-input" ${cur.includes(a)?'checked':''}> ${a}</label>`).join('')}<div class="btn-list mt-2"><button class="btn btn-primary">Save</button><button type="button" class="btn" onclick="closeModal()">Cancel</button></div></form>`);}
async function roleUpdate(e,name){e.preventDefault();const v=formVals(e.target);const perms=ROLE_ACTIONS.filter(a=>v['p_'+a]);
try{await put('/api/v1/roles/'+encodeURIComponent(name),{permissions:perms});closeModal();toast('Role updated');load();}catch(err){toast('Save failed: '+String(err).slice(0,300))}}
async function roleDel(name){if(!await confirmDlg(`Delete custom role "${name}"? Only possible when no member uses it.`))return;try{await del('/api/v1/roles/'+encodeURIComponent(name));toast('Deleted');load();}catch(e){toast(String(e).slice(0,300))}}
async function memberDel(id,email){if(!await confirmDlg(`Remove member ${email}?`))return;try{await del('/api/v1/memberships/'+id);toast('Removed');load();}catch(e){toast(String(e).slice(0,300))}}
async function userToggle(email,disable){try{await post(`/api/v1/users/${encodeURIComponent(email)}/${disable?'disable':'enable'}`,{});toast(disable?'Login disabled':'Login enabled');load();}catch(e){toast(String(e).slice(0,300))}}
async function userReset(email){if(!await confirmDlg(`Reset password for ${email}? A one-time password is shown once.`))return;try{const r=await post(`/api/v1/users/${encodeURIComponent(email)}/reset-password`,{});openModal(`<h3>One-time password</h3><div class="alert alert-warning">Shown once — deliver out-of-band:<br><b>${esc(r.temp_password)}</b></div><button class="btn" onclick="closeModal()">Close</button>`);load();}catch(e){toast(String(e).slice(0,300))}}
async function addKey(e){e.preventDefault();const f=e.target;try{const r=await post('/api/v1/apikeys',{name:f.name.value,scopes:(f.scopes.value||'read').split(',').map(s=>s.trim())});toast('KEY (shown once): '+r.key);load();}catch(err){toast(String(err).slice(0,300))}}
async function keyRevoke(id){if(!await confirmDlg('Revoke API key #'+id+'? Clients using it stop working.'))return;try{await post(`/api/v1/apikeys/${id}/revoke`,{});toast('Revoked');load();}catch(e){toast(String(e).slice(0,200))}}
async function setBudget(e){e.preventDefault();const f=e.target;try{const pid=window.costPid||(f.project_id?+f.project_id.value:await resolveProject());await post('/api/v1/costs/budget',{project_id:pid,limit:+f.limit.value||0});toast('Budget set');load();}catch(err){toast(String(err).slice(0,300))}}
async function sysDoctor(){try{document.querySelector('#doc').textContent=JSON.stringify(await api('/api/v1/system/doctor'),null,1).slice(0,3000);}catch(e){toast(String(e).slice(0,200))}}
async function flagSet(name,on){try{await post('/api/v1/flags',{name,on});toast(`Flag ${name}=${on}`);load();}catch(e){toast(String(e).slice(0,300))}}
async function maintAdd(e){e.preventDefault();const v=formVals(e.target);const s=v.starts?new Date(v.starts).getTime()/1000:0,en=v.ends?new Date(v.ends).getTime()/1000:0;
try{await post('/api/v1/maintenance',{name:v.name,starts_at:s,ends_at:en});toast('Window created');load();}catch(err){toast(String(err).slice(0,300))}}
async function maintDisable(id){try{await post(`/api/v1/maintenance/${id}/disable`,{});toast('Disabled');load();}catch(e){toast(String(e).slice(0,200))}}
async function billingPlan(){const p=prompt('Plan (starter/pro/enterprise):');if(!p)return;try{await post('/api/v1/billing/plan',{plan:p.trim()});toast('Plan updated');load();}catch(e){toast(String(e).slice(0,300))}}
async function retentionRun(){const d=prompt('Delete operational rows older than N days:','30');if(!d)return;try{const r=await post('/api/v1/admin/retention/run',{days:+d,collections:['raw','history','events']});toast('Removed: '+JSON.stringify(r.removed));load();}catch(e){toast(String(e).slice(0,400))}}
async function backupNow(btn){try{await runAction({btn:btn||document.activeElement,title:'Database backup',stages:['Dumping tables','Compressing','Ready'],
fn:async()=>{const r=await fetch('/api/v1/admin/backup',{method:'POST',headers:H()});if(!r.ok)throw new Error(r.status+' '+(await r.text()).slice(0,200));const blob=await r.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='webintel-backup.sql';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);return{};},
onDone:()=>toast('Backup downloaded')});}catch(e){toast('Backup failed: '+String(e).slice(0,200))}}
async function dqCheck(){try{const r=await api('/api/v1/admin/data-quality');const el=$('#dq');el.textContent=JSON.stringify(r,null,1).slice(0,2000);const fixable=(r.issues||[]).filter(i=>i.fixable);if(fixable.length&&confirm(`Auto-fix ${fixable.map(i=>i.kind).join(', ')}? Only safe fixes run.`)){for(const i of fixable){await post('/api/v1/admin/data-quality/fix',{kind:i.kind});}toast('Fixed');load();}}catch(e){toast(String(e).slice(0,300))}}
async function settingsView(C){const [ver,hl,orgs,keys,roles,flags,bu,ai,wh,conn,maint,verts]=await Promise.all([
api('/api/version').catch(()=>({})),api('/readyz').catch(()=>({checks:[]})),api('/api/v1/orgs').catch(()=>({items:[]})),
api('/api/v1/apikeys').catch(()=>({items:[]})),api('/api/v1/roles').catch(()=>({roles:{}})),api('/api/v1/flags').catch(()=>({flags:{}})),
api('/api/v1/billing/usage').catch(()=>({})),api('/api/v1/ai/health').catch(()=>({})),api('/api/v1/webhooks').catch(()=>({items:[]})),
api('/api/v1/connectors').catch(()=>({items:[]})),api('/api/v1/maintenance').catch(()=>({items:[]})),
api('/api/v1/verticals').catch(()=>({verticals:[]}))]);
const o=(orgs.items||[])[0]||{};
C.innerHTML=crumbs([['System','settings']])+`<h2>Settings</h2><div class="grid">
<div class="card"><div class="card-body"><h3 class="card-title">General</h3><div>Org: <b>${esc(o.name||'—')}</b> <span class="text-muted">(${esc(o.plan||'starter')})</span></div><div class="text-muted small">Slug: ${esc(o.slug||'—')} · App v${esc(ver.version||'?')} · API ${esc(ver.api||'v1')}</div><div class="btn-list mt-2"><button class="btn btn-sm" onclick="go('orgs')">Organizations</button><button class="btn btn-sm" onclick="billingPlan()">Change plan</button></div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Appearance</h3>
<label class="form-label">Theme</label><div class="btn-list mb-2">${['light','dark','system'].map(t=>`<button class="btn btn-sm ${getTheme()===t?'btn-primary':''}" onclick="setTheme('${t}');load()">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>
<label class="form-label">Sidebar</label><div class="btn-list mb-2"><button class="btn btn-sm ${document.documentElement.getAttribute('data-wi-side')!=='folded'?'btn-primary':''}" onclick="if(document.documentElement.getAttribute('data-wi-side')==='folded')toggleSidebar();load()">Expanded</button><button class="btn btn-sm ${document.documentElement.getAttribute('data-wi-side')==='folded'?'btn-primary':''}" onclick="if(document.documentElement.getAttribute('data-wi-side')!=='folded')toggleSidebar();load()">Folded</button></div>
<label class="form-label">Top navbar</label><div class="btn-list mb-2"><button class="btn btn-sm ${(localStorage.getItem('wi-nav')||'sticky')==='sticky'?'btn-primary':''}" onclick="setNavbar('sticky');load()">Sticky</button><button class="btn btn-sm ${(localStorage.getItem('wi-nav')||'sticky')==='static'?'btn-primary':''}" onclick="setNavbar('static');load()">Static</button></div>
<label class="form-label">Language</label><div class="btn-list mb-2">${[['en','English'],['id','Indonesia'],['ar','العربية']].map(([v,l])=>`<button class="btn btn-sm ${LANG===v?'btn-primary':''}" onclick="setLang('${v}')">${l}</button>`).join('')}</div>
<label class="form-label">Accent color</label><div class="btn-list mb-2">${[['blue','Blue'],['azure','Azure'],['indigo','Indigo'],['purple','Purple'],['cyan','Cyan'],['teal','Teal']].map(([v,l])=>`<button class="btn btn-sm ${getAccent()===v?'btn-primary':''}" onclick="setAccent('${v}');load()"><span class="badge bg-${v} me-1">●</span>${l}</button>`).join('')}</div>
<div class="text-muted small">Timezone: Asia/Jakarta (WIB) · Navbar theme follows page theme.</div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Security</h3><div class="text-muted small">App API keys: ${(keys.items||[]).length} · Roles: ${Object.keys(roles.roles||{}).join(', ')||'—'}</div><div class="btn-list mt-2"><button class="btn btn-sm" onclick="go('apikeys')">API keys</button><button class="btn btn-sm" onclick="go('users')">Users &amp; roles</button></div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Collectors</h3><div class="text-muted small">Connectors: ${(conn.items||[]).length} · Bright Data: ${(hl.checks||[]).find(c=>c.name==='brightdata')?.status||'?'}</div><div class="btn-list mt-2"><button class="btn btn-sm" onclick="go('connectors')">Connectors</button><button class="btn btn-sm" onclick="bdTest(this)">Test Bright Data</button></div><pre id="bd"></pre></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Browser</h3><div class="text-muted small">Status: ${(hl.checks||[]).find(c=>c.name==='browser')?.status||(hl.checks||[]).find(c=>c.name==='api')?'see health':'?'}</div><div class="btn-list mt-2"><button class="btn btn-sm" onclick="go('health')">System health</button></div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Scheduler</h3><div class="btn-list"><button class="btn btn-sm btn-primary" onclick="tick(this)">Run scheduler now</button><button class="btn btn-sm" onclick="go('schedules')">Schedules</button></div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Notifications</h3><div class="text-muted small">Channels: in-app always · email/webhook via alert rules &amp; webhooks.</div><div class="btn-list mt-2"><button class="btn btn-sm" onclick="go('webhooks')">Webhooks (${(wh.items||[]).length})</button><button class="btn btn-sm" onclick="go('alerts')">Alerts</button></div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">AI</h3><div class="text-muted small">Default provider: ${ai.ok?'● Connected':'○ Not configured'}</div><div class="btn-list mt-2"><button class="btn btn-sm" onclick="go('ai')">AI providers</button></div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Storage</h3><div class="text-muted small">Retention removes aged operational rows only (entities/evidence untouched unless listed).</div><div class="btn-list mt-2"><button class="btn btn-sm" onclick="backupNow(this)">Backup now (.sql)</button><button class="btn btn-sm btn-danger" onclick="retentionRun()">Run retention…</button><button class="btn btn-sm" onclick="dqCheck()">Data quality…</button></div><pre id="dq"></pre></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Maintenance windows</h3>${(maint.items||[]).map(m=>`<div>• ${esc(m.name)} [${m.enabled?'on':'off'}] <button class="btn btn-sm" onclick="maintDisable(${m.id})">Disable</button></div>`).join('')||'<div class="empty">None.</div>'}<form class="d-flex flex-wrap gap-2 mt-2" onsubmit="maintAdd(event)"><input name="name" class="form-control" style="max-width:150px" placeholder="name"><input name="starts" type="datetime-local" class="form-control" style="max-width:200px"><input name="ends" type="datetime-local" class="form-control" style="max-width:200px"><button class="btn btn-sm btn-primary">Add</button></form></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Feature flags</h3>${Object.entries(flags.flags||{}).map(([k,v])=>`<div>• ${esc(k)}: <b>${esc(v)}</b> <button class="btn btn-sm" onclick="flagSet('${esc(k)}',${v===true||v==='on'?false:true})">Toggle</button></div>`).join('')||'<div class="empty">None.</div>'}</div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Billing</h3><pre>${esc(JSON.stringify(bu).slice(0,500))}</pre><button class="btn btn-sm" onclick="billingPlan()">Change plan</button></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">Industry templates</h3>${(verts.verticals||[]).map(v=>`<div>• ${esc(v)} <button class="btn btn-sm" onclick="vertApply('${esc(v)}')">Apply</button></div>`).join('')||'<div class="empty">None.</div>'}<div class="text-muted small">Apply seeds watchlists for the vertical.</div></div></div>
<div class="card"><div class="card-body"><h3 class="card-title">System</h3><div class="btn-list"><button class="btn btn-sm" onclick="sysDoctor2()">Doctor</button><button class="btn btn-sm" onclick="go('audit')">Audit log</button></div><pre id="doc2"></pre></div></div>
</div>`;}
async function bdTest(btn){btn.disabled=true;try{document.querySelector('#bd').textContent=JSON.stringify(await post('/api/v1/brightdata/test',{}),null,2).slice(0,1000);}catch(e){document.querySelector('#bd').textContent=String(e).slice(0,300)}btn.disabled=false;}
async function vertApply(name){try{const r=await post(`/api/v1/verticals/${name}/apply`,{});toast(`Applied: ${r.watchlists.length} watchlists`);load();}catch(e){toast(String(e).slice(0,300))}}
async function sysDoctor2(){try{document.querySelector('#doc2').textContent=JSON.stringify(await api('/api/v1/system/doctor'),null,1).slice(0,2000);}catch(e){toast(String(e).slice(0,200))}}
/* ---------- AI providers (wizard + edit; same behavior as before) ---------- */
async function aiProvidersView(C){
let presets=[],db=[],envP={providers:[]},envH={ok:false};
try{presets=(await api('/api/v1/ai/provider-presets')).presets||[]}catch(e){}
try{db=(await api('/api/v1/ai/providers/db')).items||[]}catch(e){}
try{envP=await api('/api/v1/ai/providers')}catch(e){}
try{envH=await api('/api/v1/ai/health')}catch(e){}
window._aiPresets=presets;
const envCfg=envH.reason!=='not-configured';
const badge=p=>{
if(!p.enabled)return '<span class="status">Disabled</span>';
if(p.last_test_status==='passed')return '<span class="status ok">● Connected</span>';
if(p.last_test_status==='failed')return '<span class="status err">● Connection failed</span>';
return '<span class="status">● Not tested</span>'};
const tested=p=>p.last_tested_at?new Date(p.last_tested_at*1000).toLocaleString():'—';
const lat=p=>(p.last_test_latency_ms!=null&&p.last_tested_at)?p.last_test_latency_ms+' ms':'—';
const cards=db.map(p=>`<div class="card"><div class="card-body">
<div class="d-flex align-items-center gap-2 flex-wrap"><h3 class="card-title m-0">${esc(p.name)}</h3>${badge(p)}<span class="text-muted small">${esc(p.preset||p.protocol||'')}</span></div>
<div class="text-muted small mt-1">Model: <b>${esc(p.model||'—')}</b> · Protocol: ${esc(p.protocol||'chat')}</div>
<div class="text-muted small">Last tested: ${tested(p)}${p.last_tested_at?' · Latency: '+lat(p):''}${p.last_test_status==='failed'&&p.last_test_error?' · <span class="text-danger">'+esc(p.last_test_error)+'</span>':''}</div>
<div class="btn-list mt-2"><button class="btn btn-sm" id="t${p.id}" onclick="aiRowTest(${p.id})">Test connection</button><button class="btn btn-sm" onclick="aiEditOpen(${p.id})">Edit</button><button class="btn btn-sm btn-danger" onclick="aiDelete(${p.id},'${esc(p.name).replace(/'/g,"\\'")}')">Delete</button><button class="btn btn-sm" onclick="aiToggle(${p.id},${p.enabled?0:1})">${p.enabled?'Disable':'Enable'}</button></div>
</div></div>`).join('');
const envCard=envCfg?`<div class="card"><div class="card-body"><div class="d-flex align-items-center gap-2"><h3 class="card-title m-0">Muse Spark <span class="text-muted small">(environment)</span></h3>${envH.ok?'<span class="status ok">● Connected</span>':'<span class="status err">● Connection failed</span>'}</div><div class="text-muted small mt-1">Model: <b>${esc((envP.models||[])[0]||'—')}</b> · Read-only, managed via server environment.</div></div></div>`:'';
C.innerHTML=crumbs([['AI','ai']])+`<div class="d-flex align-items-center flex-wrap gap-2 mb-3"><div><h2 class="m-0">AI Providers</h2><div class="text-muted small">Manage configured AI providers, credentials, connection status, and models. App API keys are managed separately under System → apikeys.</div></div><div class="ms-auto"><button class="btn btn-primary" onclick="aiWizardOpen()">+ Add AI provider</button></div></div>
<div class="grid">${envCard}${cards}</div>
${(!db.length&&!envCfg)?'<div class="card"><div class="card-body"><div class="empty"><h3>No AI providers configured.</h3><p>Add an AI provider to enable AI-powered features.</p><button class="btn btn-primary" onclick="aiWizardOpen()">+ Add AI provider</button></div></div></div>':''}
<div class="card"><div class="card-body"><h3 class="card-title">Ask (evidence-grounded)</h3><form class="d-flex flex-wrap gap-2" onsubmit="chat(event)"><input name="q" class="form-control" style="max-width:320px" aria-label="question"><button class="btn btn-primary">Send</button></form><pre id="ans"></pre></div></div>
<div id="ai-modal"></div>`;
}
function aiModal(html){const m=$('#ai-modal');m.innerHTML=`<div style="position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:2000;display:flex;align-items:flex-start;justify-content:center;overflow:auto;padding:2rem 1rem" onclick="if(event.target===this)aiModalClose()"><div class="card" style="width:100%;max-width:640px" role="dialog" aria-modal="true"><div class="card-body">${html}</div></div></div>`;const f=m.querySelector('input,select,button');if(f)f.focus();}
function aiModalClose(){const m=$('#ai-modal');if(m)m.innerHTML='';}
let WIZ=null;
function aiWizardOpen(){WIZ={step:1,preset:null,name:'',endpoint:'',key:'',model:'',models:[],manual:false,tested:false,testing:false,result:null};aiWizardRender();}
function aiWizardRender(){const P=window._aiPresets||[];
if(WIZ.step===1){aiModal(`<h3>Select AI provider</h3><p class="text-muted">Choose a provider to configure. Only connection details you enter are used.</p><div class="grid">${P.map(p=>`<button id="preset-${p.id}" class="card text-start" style="cursor:pointer;text-align:left" onclick="aiWizardPick('${p.id}')"><div class="card-body"><b>${esc(p.display_name)}</b><div class="text-muted small">${esc(p.description)}</div><div class="text-muted small mt-1">Auth: ${esc(p.auth==='optional_key'?'optional key':'API key')} · Protocol: ${esc(p.protocol)}</div></div></button>`).join('')}</div><div class="mt-2"><button class="btn" onclick="aiModalClose()">Cancel</button></div>`);return;}
const pr=WIZ.preset,ro=pr.endpoint_mode==='fixed',needEp=pr.endpoint_mode!=='fixed';
const modelBox=WIZ.models.length?`<label class="form-label">Model</label><select id="wmodel" class="form-select" aria-label="model">${WIZ.models.map(m=>`<option ${m.id===WIZ.model?'selected':''}>${esc(m.id)}</option>`).join('')}</select>`:`<label class="form-label">Model</label><input id="wmodel" class="form-control" value="${esc(WIZ.model)}" placeholder="${pr.discovery?'Discover via Test connection':'Type model id'}" aria-label="model">${WIZ.manual?'<div class="text-muted small mt-1">Model discovery is not supported by this provider — type the model id.</div>':''}`;
aiModal(`<h3>${esc(pr.display_name)}</h3><p class="text-muted">${esc(pr.description)}</p>
<label class="form-label">Configuration name</label><input id="wname" class="form-control" value="${esc(WIZ.name||pr.display_name)}" aria-label="configuration name">
${needEp?`<label class="form-label mt-2">Endpoint</label><input id="wep" class="form-control" value="${esc(WIZ.endpoint||pr.default_endpoint)}" ${ro?'readonly':''} aria-label="endpoint">`:''}
<label class="form-label mt-2">${esc(pr.key_label)}</label><input id="wkey" type="password" class="form-control" value="" placeholder="${pr.key_required?'(required)':'(optional)'}" autocomplete="new-password" aria-label="api key">
<div class="mt-2">${modelBox}</div>
<details class="mt-2"><summary class="text-muted">Advanced settings</summary><div class="text-muted small mt-1">Protocol: <b>${esc(pr.protocol)}</b> · Model discovery: <b>${pr.discovery?'supported':'manual entry'}</b> · Credentials are encrypted server-side and never shown again.</div></details>
<div id="wres" class="mt-2">${WIZ.result?aiTestResultHtml(WIZ.result):''}</div>
<div class="btn-list mt-3"><button class="btn" id="wtest" onclick="aiWizardTest()" ${WIZ.testing?'disabled':''}>${WIZ.testing?'<span class="spinner-border spinner-border-sm me-1"></span>Testing…':'Test connection'}</button><button class="btn btn-primary" onclick="aiWizardSave()" ${WIZ.tested?'':'disabled'}>Save provider</button><button class="btn" onclick="aiModalClose()">Cancel</button></div>
${WIZ.tested?'':'<div class="text-muted small mt-1">Test the connection first — saving requires a successful test.</div>'}`);}
function aiWizardPick(id){const pr=(window._aiPresets||[]).find(p=>p.id===id);if(!pr)return;WIZ.preset=pr;WIZ.step=2;WIZ.name=pr.display_name;WIZ.endpoint=pr.default_endpoint||'';WIZ.model=pr.default_model||'';WIZ.models=[];WIZ.manual=!pr.discovery;WIZ.tested=false;WIZ.result=null;aiWizardRender();}
async function aiWizardTest(){const pr=WIZ.preset;WIZ.name=$('#wname').value.trim();if(pr.endpoint_mode!=='fixed')WIZ.endpoint=$('#wep').value.trim();const k=$('#wkey').value;if(k)WIZ.key=k;const ms=$('#wmodel');if(ms)WIZ.model=ms.value.trim();
if(!WIZ.name){toast('Name required');return}
if(pr.endpoint_mode==='required'&&!WIZ.endpoint){toast('Endpoint required');return}
if(pr.key_required&&!WIZ.key){toast('API key required');return}
WIZ.testing=true;aiWizardRender();
try{const r=await post('/api/v1/ai/providers/db/test',{name:WIZ.name,preset:pr.id,protocol:pr.protocol,base_url:WIZ.endpoint||pr.default_endpoint,api_key:WIZ.key,model:WIZ.model});WIZ.result=r;WIZ.tested=!!r.success;
if(r.success&&r.models&&r.models.length){WIZ.models=r.models;if(!WIZ.model&&r.models[0])WIZ.model=r.models[0].id;}
if(r.success&&(!r.models||!r.models.length)){WIZ.manual=true;}
}catch(e){WIZ.result={success:false,error:{code:'REQUEST_FAILED',message:String(e).slice(0,200)}};WIZ.tested=false;}
WIZ.testing=false;aiWizardRender();}
function aiTestResultHtml(r){if(r.success){return `<div class="alert alert-success"><b>✓ Connection successful</b><div class="small">Provider: ${esc(r.provider.name)} · Authentication: valid · Model: ${esc(r.model.selected||'—')} (${r.model.available?'available':'unverified'}) · Latency: ${r.connection.latency_ms} ms · Models discovered: ${r.models.length}</div></div>`;}
const e=r.error||{};return `<div class="alert alert-danger"><b>✕ Connection failed</b><div class="small">${esc(e.message||'failed')}${e.code?' · HTTP/code: '+esc(e.code):''}${e.suggested_action?'<br>Suggested action: '+esc(e.suggested_action):''}</div></div>`;}
async function aiWizardSave(){const nm=$('#wname');if(nm&&nm.value.trim())WIZ.name=nm.value.trim();const wm=$('#wmodel');if(wm&&wm.value.trim())WIZ.model=wm.value.trim();try{await post('/api/v1/ai/providers/db',{name:WIZ.name,preset:WIZ.preset.id,protocol:WIZ.preset.protocol,base_url:WIZ.endpoint||WIZ.preset.default_endpoint,api_key:WIZ.key,model:WIZ.model});aiModalClose();toast('Provider saved');load();}catch(e){toast('Save failed: '+String(e).slice(0,200))}}
async function aiRowTest(id){const b=$('#t'+id);if(b){b.disabled=true;b.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Testing…';}
try{const r=await post(`/api/v1/ai/providers/db/${id}/test`,{});toast(r.success?`✓ Connected (${r.connection.latency_ms} ms)`:`✕ ${((r.error||{}).message||'failed')}`)}catch(e){toast('✕ '+String(e).slice(0,200))}
load();}
async function aiToggle(id,en){try{await post(`/api/v1/ai/providers/db/${id}/${en?'enable':'disable'}`,{});load();}catch(e){toast(String(e).slice(0,200))}}
async function aiDelete(id,name){if(!await confirmDlg(`Delete provider "${name}"? The stored credential will be removed.`))return;try{await api(`/api/v1/ai/providers/db/${id}`,{method:'DELETE'});toast('Deleted');}catch(e){toast(String(e).slice(0,200))}load();}
async function aiEditOpen(id){let p;try{p=await api(`/api/v1/ai/providers/db/${id}`)}catch(e){toast(String(e).slice(0,200));return}
window._aiEdit={id,changeKey:false,models:p.model?[p.model]:[],manual:false};
aiModal(`<h3>Edit provider</h3><label class="form-label">Provider (read-only)</label><input class="form-control" value="${esc(p.preset||p.protocol||'')}" readonly>
<label class="form-label mt-2">API key</label><div id="ekeywrap"><input class="form-control" value="••••••••••••••••" readonly><button class="btn btn-sm mt-1" onclick="aiEditKey()">Change API key</button></div>
<label class="form-label mt-2">Model</label><div class="d-flex gap-2"><select id="emodel" class="form-select" aria-label="model">${window._aiEdit.models.map(m=>`<option ${m===p.model?'selected':''}>${esc(m)}</option>`).join('')}</select><button class="btn btn-sm" id="ediscover" onclick="aiEditDiscover(${id})">Discover</button></div><div id="eres" class="text-muted small mt-1"></div>
<div class="btn-list mt-3"><button class="btn" id="etest" onclick="aiEditTest(${id})">Test connection</button><button class="btn btn-primary" onclick="aiEditSave(${id})">Save changes</button><button class="btn" onclick="aiModalClose()">Cancel</button></div><div id="esaveres" class="mt-2"></div>`);}
function aiEditKey(){window._aiEdit.changeKey=true;$('#ekeywrap').innerHTML='<input id="ekey" type="password" class="form-control" placeholder="new API key" autocomplete="new-password" aria-label="new api key">';}
async function aiEditDiscover(id){const b=$('#ediscover');b.disabled=true;b.textContent='Discovering…';try{const r=await post(`/api/v1/ai/providers/db/${id}/models`,{});const sel=$('#emodel');
if(r.models&&r.models.length){window._aiEdit.models=r.models.map(m=>m.id);sel.innerHTML=r.models.map(m=>`<option>${esc(m.id)}</option>`).join('');$('#eres').textContent=r.models.length+' models discovered';}
else{$('#eres').textContent=(r.note||((r.error||{}).message)||'Manual entry — discovery not supported');const inp=document.createElement('input');inp.id='emodel';inp.className='form-control';inp.value=sel.value;sel.replaceWith(inp);}}catch(e){$('#eres').textContent=String(e).slice(0,200)}b.disabled=false;b.textContent='Discover';}
async function aiEditTest(id){const b=$('#etest');b.disabled=true;b.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Testing…';
const body={};const m=$('#emodel');if(m)body.model=m.value.trim();const k=$('#ekey');if(k&&k.value)body.api_key=k.value;
try{if(body.model||body.api_key)await post(`/api/v1/ai/providers/db/${id}`,body);}catch(e){}
let r;try{r=await post(`/api/v1/ai/providers/db/${id}/test`,{});}catch(e){r={success:false,error:{message:String(e).slice(0,200)}}}
$('#esaveres').innerHTML=aiTestResultHtml(r);b.disabled=false;b.textContent='Test connection';}
async function aiEditSave(id){const body={};const m=$('#emodel');if(m)body.model=m.value.trim();const k=$('#ekey');if(k&&k.value)body.api_key=k.value;
try{await post(`/api/v1/ai/providers/db/${id}`,body);aiModalClose();toast('Saved');load();}catch(e){toast('Save failed: '+String(e).slice(0,200))}}
