async function invLink(id,kind){const ids=prompt('Comma-separated IDs to link:');if(!ids)return;const arr=ids.split(',').map(s=>+s.trim()).filter(Boolean);if(!arr.length)return;try{const r=await post(`/api/v1/investigations/${id}/links`,{kind,ids:arr});toast(`Linked ${r.added.length}`);load();}catch(e){toast(String(e).slice(0,300))}}
async function invCollect(id,btn){try{const d=await api('/api/v1/investigations/'+id);const tids=(d.linked.targets||[]).map(t=>t.id);
if(!tids.length){toast('No target linked — link a target first.');return;}
await runAction({btn,title:'Start collection',stages:['Queueing collection','Running recon','Linking results'],
fn:async(op)=>{const t=await api('/api/v1/targets/'+tids[0]);const j=await post('/api/v1/jobs',{project_id:t.project_id,target_id:t.id,url:t.url,strategy:'AUTO',profile:'standard'});opStage(op.id,'Running recon');const r=await api(`/api/v1/jobs/${j.job_id}/run`,{method:'POST',body:'{}',timeout:180000,slowAfter:15000});return{...r,job_id:j.job_id};},
onDone:(r)=>{toast(r.status==='success'?'Collection completed.':'Collection finished: '+r.status);window.DTAB['investigation']='Jobs';load();}});}catch(e){toast('Collection failed: '+String(e).slice(0,250));}}
