async function invGraph(d){const box=$('#igv');if(!box)return;try{
const keys=[];(d.linked.entities||[]).forEach(e=>{if(e.domain)keys.push(e.domain);if(e.name)keys.push(e.name);});
let nodes=[];for(const k of keys.slice(0,8)){try{const r=await api('/api/v1/graph/nodes?q='+encodeURIComponent(k)+'&size=20');nodes=nodes.concat(r.items||[]);}catch(e){}}
nodes=nodes.filter((n,i,a)=>a.findIndex(x=>x.id===n.id)===i).slice(0,12);
window._invNodes=nodes.map(n=>n.id);window._invId=d.id;
const views=((d.data||{}).views)||{};
let html=`<div class="btn-list mb-2"><button class="btn btn-sm" onclick="invViewSave(${d.id})">Save current view…</button>${Object.keys(views).map(v=>`<button class="btn btn-sm" onclick="invViewLoad(${d.id},'${esc(v).replace(/'/g,"\\'")}')">${esc(v)}</button>`).join('')}</div>`;
if(!nodes.length){box.innerHTML=html+'<div class="empty">No graph nodes match the linked entities yet — add nodes in Knowledge → graph.</div>';return;}
html+=`<div class="text-muted small mb-2">${nodes.length} node(s).</div>`;
for(const n of nodes.slice(0,4)){try{const r=await api(`/api/v1/graph/render?node=${n.id}`);html+=`<div class="card mb-2"><div class="card-body"><b>${esc(n.name||n.key)}</b> (${esc(n.kind||'')})<div>${r.svg||''}</div></div></div>`;}catch(e){}}
box.innerHTML=html;}catch(e){box.innerHTML=`<div class="empty">Error: ${esc(e)}</div>`;}}
async function invViewSave(id){const name=prompt('View name:');if(!name)return;const nodes=window._invNodes||[];if(!nodes.length){toast('Nothing to save — expand the graph first');return}
try{await post(`/api/v1/investigations/${id}/views`,{name,node_ids:nodes});toast('View saved');load();}catch(e){toast(String(e).slice(0,200))}}
async function invViewLoad(id,name){try{const d=await api('/api/v1/investigations/'+id);const v=(((d.data||{}).views)||{})[name];if(!v){toast('View gone');return}
const box=$('#igv');let html=`<div class="text-muted small mb-2">View “${esc(name)}” (${v.node_ids.length} nodes).</div>`;
for(const nid of v.node_ids.slice(0,6)){try{const r=await api(`/api/v1/graph/render?node=${nid}`);const n=(await api('/api/v1/graph/nodes?q=&size=100')).items.find(x=>x.id===nid);html+=`<div class="card mb-2"><div class="card-body"><b>${esc((n&&(n.name||n.key))||('#'+nid))}</b><div>${r.svg||''}</div></div></div>`;}catch(e){}}
html+=`<button class="btn btn-sm btn-danger" onclick="invViewDel(${id},'${esc(name).replace(/'/g,"\\'")}')">Delete view</button>`;box.innerHTML=html;}catch(e){toast(String(e).slice(0,200))}}
async function invViewDel(id,name){if(!await confirmDlg(`Delete view "${name}"?`))return;try{await del(`/api/v1/investigations/${id}/views/${encodeURIComponent(name)}`);toast('Deleted');load();}catch(e){toast(String(e).slice(0,200))}}
async function caseGraph(d){const box=$('#igv');if(!box)return;try{
const keys=[];(d.linked.entities||[]).forEach(e=>{if(e.domain)keys.push(e.domain);if(e.name)keys.push(e.name);});
let nodes=[];for(const k of keys.slice(0,8)){try{const r=await api('/api/v1/graph/nodes?q='+encodeURIComponent(k)+'&size=20');nodes=nodes.concat(r.items||[]);}catch(e){}}
nodes=nodes.filter((n,i,a)=>a.findIndex(x=>x.id===n.id)===i).slice(0,12);
if(!nodes.length){box.innerHTML='<div class="empty">No graph nodes match the linked entities yet — add nodes in Knowledge → graph.</div>';return;}
box.innerHTML=`<div class="text-muted small mb-2">${nodes.length} node(s).</div>`+nodes.slice(0,4).map(n=>`<div class="card mb-2"><div class="card-body"><b>${esc(n.name||n.key)}</b> (${esc(n.kind||'')}) <button class="btn btn-sm" onclick="go('graph')">Open in graph</button></div></div>`).join('');
}catch(e){box.innerHTML=`<div class="empty">Error: ${esc(e)}</div>`;}}
function riskHtml(r){if(r.error)return `<div class="alert alert-danger">${esc(r.error)}</div>`;
return `<div class="alert ${r.score>=50?'alert-danger':r.score>=25?'alert-warning':'alert-success'}"><b>Risk ${r.score}/100 (${esc(r.level)})</b>${(r.factors||[]).map(f=>`<div class="small">• +${f.points} ${esc(f.name)} — ${esc(f.why)}</div>`).join('')||'<div class="small">No risk factors.</div>'}</div>`;}
async function targetRisk(id){const box=$('#riskbox');box.innerHTML='<div class="text-muted">Scoring…</div>';try{box.innerHTML=riskHtml(await api('/api/v1/risk/target/'+id));}catch(e){box.innerHTML=`<div class="empty">Error: ${esc(e)}</div>`;}}
async function entRisk(id){const box=$('#riskbox');box.innerHTML='<div class="text-muted">Scoring…</div>';try{box.innerHTML=riskHtml(await api('/api/v1/risk/entity/'+id));}catch(e){box.innerHTML=`<div class="empty">Error: ${esc(e)}</div>`;}}
function fndSel(id,on){const st=window.pgFnd;on?st.sel.add(id):st.sel.delete(id);}
